`mergePreferences` accepts readonly preference objects and returns a fresh deep merge. Later objects override earlier objects. Plain records merge recursively; arrays and primitive values replace earlier values. Every retained record and array, including arrays nested inside arrays, must be copied so the result shares no mutable record or array with any input. `undefined` is an ordinary overriding value. Empty input returns a new empty object. Inputs must not be mutated. Symbol keys and enumerable own string keys must be preserved; inherited and non-enumerable properties are ignored.

Known-bad source:

export type PreferenceRecord = { [key: PropertyKey]: unknown };

function isRecord(value: unknown): value is PreferenceRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function cloneValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value;
  }
  if (isRecord(value)) {
    return mergePreferences([value]);
  }
  return value;
}

export function mergePreferences(
  sources: readonly Readonly<PreferenceRecord>[],
): PreferenceRecord {
  const result: PreferenceRecord = {};

  for (const source of sources) {
    for (const key of Reflect.ownKeys(source)) {
      const descriptor = Object.getOwnPropertyDescriptor(source, key);
      if (descriptor?.enumerable !== true) {
        continue;
      }
      const incoming = source[key];
      const existing = result[key];
      result[key] = isRecord(existing) && isRecord(incoming)
        ? mergePreferences([existing, incoming])
        : cloneValue(incoming);
    }
  }

  return result;
}

