import { mergePreferences, type PreferenceRecord } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const symbolKey = Symbol("setting");
const nestedArray = [{ enabled: true }, [1, { deep: "value" }]];
const first: PreferenceRecord = {
  theme: { color: "blue", spacing: 4 },
  list: nestedArray,
  primitive: 1,
  erased: "present",
};
first[symbolKey] = { from: "first" };
const second: PreferenceRecord = {
  theme: { color: "red", nested: { active: true } },
  primitive: "later",
  erased: undefined,
};
second[symbolKey] = { from: "second", extra: [2, 3] };
Object.defineProperty(second, "hidden", { value: "ignored", enumerable: false });
const prototype = { inherited: "ignored" };
const third = Object.create(prototype) as PreferenceRecord;
third.own = "kept";

const result = mergePreferences([first, second, third]);
const theme = result.theme as PreferenceRecord;
equal(theme.color, "red", "later nested value overrides");
equal(theme.spacing, 4, "earlier nested key retained");
equal((theme.nested as PreferenceRecord).active, true, "new nested record retained");
equal(result.primitive, "later", "primitive replaced");
assert(Object.prototype.hasOwnProperty.call(result, "erased"), "undefined remains an own override");
equal(result.erased, undefined, "undefined overrides normally");
equal(result.own, "kept", "enumerable own key included");
assert(!Object.prototype.hasOwnProperty.call(result, "inherited"), "inherited key ignored");
assert(!Object.prototype.hasOwnProperty.call(result, "hidden"), "non-enumerable key ignored");
const symbolResult = result[symbolKey] as PreferenceRecord;
equal(symbolResult.from, "second", "symbol key preserved and overridden");

const clonedList = result.list as unknown[];
assert(clonedList !== nestedArray, "outer array copied");
assert(clonedList[0] !== nestedArray[0], "record in array copied");
assert(clonedList[1] !== nestedArray[1], "nested array copied");
const originalInner = nestedArray[1] as unknown[];
const clonedInner = clonedList[1] as unknown[];
assert(clonedInner[1] !== originalInner[1], "record inside nested array copied");
assert(theme !== first.theme && theme !== second.theme, "merged record shares neither input record");
assert(theme.nested !== (second.theme as PreferenceRecord).nested, "nested record copied");
assert(symbolResult !== second[symbolKey], "symbol-keyed record copied");
assert(symbolResult.extra !== (second[symbolKey] as PreferenceRecord).extra, "symbol-keyed nested array copied");

(clonedList[0] as PreferenceRecord).enabled = false;
equal((nestedArray[0] as PreferenceRecord).enabled, true, "result mutation does not affect input");
(theme.nested as PreferenceRecord).active = false;
equal(((second.theme as PreferenceRecord).nested as PreferenceRecord).active, true, "merged result is independent");

const replacementSource: PreferenceRecord = { value: { old: true } };
const replacementArray = [{ fresh: true }];
const replaced = mergePreferences([replacementSource, { value: replacementArray }]);
assert(Array.isArray(replaced.value), "array replaces record rather than merging");
assert(replaced.value !== replacementArray, "replacement array copied");

const emptyA = mergePreferences([]);
const emptyB = mergePreferences([]);
equal(Reflect.ownKeys(emptyA).length, 0, "empty input result");
assert(emptyA !== emptyB, "empty result is fresh");

